int main(void) {
	unsigned n = (unsigned)(sizeof(yt_cases)/sizeof(yt_cases[0]));
	unsigned pass = 0, fail = 0;
	for (unsigned i = 0; i < n; ++i) {
		if (yt_cases[i].fn() == 0) pass++;
		else { fail++; fprintf(stderr, "FAIL: %s\n", yt_cases[i].name); }
	}
	printf("xent yoga full: %u passed, %u failed of %u\n", pass, fail, n);
	return fail ? 1 : 0;
}
